-- Tabel baru ss2_ saja; tabel lama tidak dihapus/diubah.
CREATE TABLE IF NOT EXISTS ss2_users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('customer','admin') NOT NULL DEFAULT 'customer',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ss2_products(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,description TEXT,price INT UNSIGNED NOT NULL DEFAULT 0,category VARCHAR(80) NOT NULL DEFAULT 'Camilan',emoji VARCHAR(16) NOT NULL DEFAULT '🍽️',stock INT UNSIGNED NOT NULL DEFAULT 0,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ss2_orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,total BIGINT UNSIGNED NOT NULL DEFAULT 0,status ENUM('pending','processing','ready','completed','cancelled') NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id),FOREIGN KEY(user_id) REFERENCES ss2_users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ss2_order_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,product_name VARCHAR(150) NOT NULL,quantity INT UNSIGNED NOT NULL,unit_price INT UNSIGNED NOT NULL,FOREIGN KEY(order_id) REFERENCES ss2_orders(id) ON DELETE CASCADE,INDEX(product_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO ss2_products(name,description,price,category,emoji,stock) SELECT 'Piscok Lumer','Pisang cokelat dengan isian lumer.',8000,'Manis','🍌',30 WHERE NOT EXISTS(SELECT 1 FROM ss2_products);
INSERT INTO ss2_products(name,description,price,category,emoji,stock) SELECT 'Risol Mayo','Renyah dengan mayo creamy.',5000,'Gurih','🥟',30 WHERE (SELECT COUNT(*) FROM ss2_products)=1;
INSERT INTO ss2_products(name,description,price,category,emoji,stock) SELECT 'Cireng Isi','Cireng kenyal, isi gurih.',4000,'Gurih','🧀',30 WHERE (SELECT COUNT(*) FROM ss2_products)=2;
